const cenas = $input.first().json.message.content.cenas;
const output = {};

if (cenas && Array.isArray(cenas)) {
  for (let i = 0; i < Math.min(cenas.length, 8); i++) {
    output[`original${i + 1}`] = cenas[i].original;
    output[`imagemPrompt${i + 1}`] = cenas[i].imagemPrompt;
  }
}

return [
  {
    json: output,
  },
];

function formatarTempo(segundos) {
    const horas = Math.floor(segundos / 3600);
    const minutos = Math.floor((segundos % 3600) / 60);
    const segs = Math.floor(segundos % 60);
    const milis = Math.floor((segundos % 1) * 1000);

    return `${String(horas).padStart(2, '0')}:${String(minutos).padStart(2, '0')}:${String(segs).padStart(2, '0')},${String(milis).padStart(3, '0')}`;
}

function gerarSRT(output, duracaoTotal) {
    let srt = '';

    if (Array.isArray(output) && output.length > 0) {
        output = output[0].output || "Texto não encontrado";
    }

    if (typeof output === 'string') {
        // Quebrar o texto em frases usando pontuação
        const frases = output.split(/(?<=[.!?])\s+/).filter(f => f.trim());

        // Criar chunks de até 5 palavras por frase
        const chunks = [];
        frases.forEach(frase => {
            const palavras = frase.split(' ');
            for (let i = 0; i < palavras.length; i += 5) {
                chunks.push(palavras.slice(i, i + 5).join(' '));
            }
        });

        // Calcular tempo proporcional para cada chunk
        const tempoPorChunk = duracaoTotal / chunks.length;

        chunks.forEach((chunk, index) => {
            const inicio = index * tempoPorChunk;
            const fim = (index + 1) * tempoPorChunk;

            srt += `${index + 1}\n`;
            srt += `${formatarTempo(inicio)} --> ${formatarTempo(fim)}\n`;
            srt += `${chunk}\n\n`;
        });
    } else {
        srt = "Erro: Estrutura do output inesperada.\n";
    }

    return srt;
}

// Pegar a duração real do áudio do FFmpeg
const output = $node["atualiza_info"].json["Descrição"];
const duracao = Number($('SSH5').item.json.stdout); // Convertendo para número

if (isNaN(duracao) || duracao <= 0) {
    return { json: { error: "Duração do áudio inválida." } };
}

const srtFinal = gerarSRT(output, duracao);
return { json: { srt: srtFinal } };

// Captura todas as URLs do input atual
const links = $input.item.json.url || [];

// Retorna no formato esperado
return [
  {
    json: {
      links: links
    }
  }
];

// 1. Obtém o valor de content do item atual
let contentValue = $('SSH5').item.json.stdout || "0";

// 2. Substitui vírgula por ponto, se existir
contentValue = contentValue.replace(",", ".");

// 3. Converte para número de ponto flutuante
const numberValue = parseFloat(contentValue);

// 4. Divide por 10 e mantém 3 casas decimais
const result = Number((numberValue / 10));

// 5. Retorna no formato esperado pelo n8n (array de objetos)
return [
  {
    json: {
      finalResult: result
    }
  }
];

const images = $('Edit Fields3').item.json.Imagens;
const audio = $('Edit Fields3').item.json.Audio;
const subtitles = $('Edit Fields3').item.json.Legendas;
const timePerImage = Number($('Edit Fields3').item.json['Tempo De Cada Imagem']);
const audioDuration = timePerImage * 10;
const imageDuration = Math.ceil(audioDuration / images.length);

// Download das legendas (executar separadamente seria ideal para melhor controle)
const downloadCommand = `wget "${subtitles}" -O /tmp/subs.srt && `;

// Comando FFmpeg principal
let ffmpegCommand = 'ffmpeg -hide_banner';

// Input das imagens
images.forEach((image, i) => {
    ffmpegCommand += ` -loop 1 -t ${audioDuration} -i "${image}"`;
});

// Input de áudio
ffmpegCommand += ` -i "${audio}"`;

// Filtros
let filters = [];

// Escalar todas as imagens para 1280x720 com padding para manter o formato correto (FORMATO DEITADO)
for (let i = 0; i < images.length; i++) {
    filters.push(`[${i}:v]scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2:white[v${i}scaled]`);
}

// Transições entre imagens
for (let i = 0; i < images.length - 1; i++) {
    const offset = i * imageDuration;
    if (i === 0) {
        filters.push(`[v0scaled][v1scaled]xfade=transition=fade:duration=1:offset=${offset}[vf0]`);
    } else {
        filters.push(`[vf${i-1}][v${i+1}scaled]xfade=transition=fade:duration=1:offset=${offset}[vf${i}]`);
    }
}

// Legendas configuradas
const lastIndex = images.length - 2;
filters.push(`[vf${lastIndex}]subtitles=/tmp/subs.srt:
    force_style='
    Fontname=Arial Bold,
    Fontsize=30,
    Alignment=2,
    MarginV=60,
    PrimaryColour=&HFFFFFF&,
    OutlineColour=&H000000&,
    BorderStyle=3,
    Outline=2,
    Shadow=0,
    Bold=1,
    AssemblyMode=1,
    LineAlignment=Center':
    charenc=UTF-8
[outv]`);

// Adicionar filtros ao comando
ffmpegCommand += ' -filter_complex "' + filters.join(';') + '"';

// Configurações de saída (FORMATO DEITADO 1280x720)
ffmpegCommand += ' -map "[outv]"' +
                     ' -map ' + images.length + ':a' +
                     ' -c:v libx264' +
                     ' -preset medium' +
                     ' -profile:v main' +
                     ' -crf 20' +
                     ' -c:a aac' +
                     ' -ar 48000' +
                     ' -b:a 192k' +
                     ' -pix_fmt yuv420p' +
                     ' -r 30' +
                     ' -max_muxing_queue_size 4096' +
                     ' -t ' + audioDuration +
                     ' -s 1280x720' + // Definindo a resolução do vídeo para 1280x720 (16:9)
                     ' -aspect 16:9' + // Definindo a proporção de tela para 16:9
                     ' -y output.mp4';

// Comando final
const finalCommand = downloadCommand + ffmpegCommand;

return { json: { command: finalCommand } };
